import{_ as o,l as r,o as a,c as i,v as n,p as d,x as t,d as s,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"Menkveld 高频做市实证","description":"","frontmatter":{"title":"Menkveld 高频做市实证","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/menkveld-hft-mm.md","filePath":"quant/menkveld-hft-mm.md","lastUpdated":1789023840000}'),m={name:"quant/menkveld-hft-mm.md"};function h(c,e,B,u,A,_){const l=r("Mermaid");return a(),i("div",null,[e[1]||(e[1]=n('<h1 id="menkveld-高频做市实证" tabindex="-1">Menkveld 高频做市实证 <a class="header-anchor" href="#menkveld-高频做市实证" aria-label="Permalink to &quot;Menkveld 高频做市实证&quot;">​</a></h1><div class="epigraph"><p>高频交易者可以是新的市场做市商：一天进出成千上万次，隔夜几乎不持仓，用速度管理库存而不是用宽价差硬扛。他们占成交的份额高，不等于占库存风险的份额高。</p><footer>—— Menkveld, High frequency trading and the new market makers, Journal of Financial Economics, 2013</footer></div><p><a href="/quant/speed-race-sniping">速度竞赛</a>把 HFT 写成狙击。缺口是经验：至少一部分高频参与者的日内轨迹更像 Ho–Stoll 做市，而不是只在新闻窗口吃过时报价。Menkveld（2013）跟踪 Chi-X 与欧洲样本里的大型高频做市商：多场所同时报价、库存均值回复、隔夜接近平仓。本课写这条实证画像，不把 HFT 定义成单一策略。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理论给出两种高频：狙击者与做市者。数据若只有匿名成交，两者都显示为高消息率、高成交份额。要分开，需要看：(i) 是否经常双边挂单；(ii) 库存是否围绕零快速回复；(iii) 利润来自价差还是来自方向性中点移动；(iv) 新闻窗口行为是否与平时不同。Menkveld 的案例表明，新做市商用多市场对冲把库存风险压到日内，进入成本是技术而不是交易所席位。这与 Grossman–Miller 的 \\(M\\) 内生一致：技术降低在场成本，\\(M\\) 增加，折让下降——在平静期。</p><p>问题是把「新做市商」写进市场质量：价差、深度、发现，哪些改善来自他们的在场，哪些恶化来自他们的撤退与狙击腿。</p><h3 id="隔夜库存接近零的含义" tabindex="-1">隔夜库存接近零的含义 <a class="header-anchor" href="#隔夜库存接近零的含义" aria-label="Permalink to &quot;隔夜库存接近零的含义&quot;">​</a></h3><p>传统专家隔夜持仓，要求隔夜风险溢价，开盘价差含库存。高频做市商把风险扔回隔夜投资者，自己做日内即时性。开收盘的流动性因此更依赖愿意隔夜的人，高频在场的时段与不在场的时段质量可以分叉。这不是道德评价，是风险分担的时间重分配。</p><p><span class="marginnote">Menkveld（2016）年审综述把 HFT 经济学收成更宽的地图。本课以 2013 年做市商画像为机制，避免把综述写成词条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>识别某一列 HFT：交易所或数据商的标记、账户层科研数据、或行为过滤（高撤单、低隔夜、双边）。刻画库存过程：半衰期、对中点的偏度（是否符合 Ho–Stoll）、跨市场净头寸。利润分解：实现价差 vs 随后中点走失（Stoll 会计）。比较该列在场与不在场的时段（工具：系统中断、费用变更、托管开通）。</p><p>Hendershott、Jones 与 Menkveld（2011）用自动报价引入作为算法交易的冲击，发现流动性改善。那是更宽的 AT，不单是 HFT 做市，但同方向：自动化降低做市的处理成本项。</p>',12)),(a(),d(p,null,{default:t(()=>[E(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MM%5B%22%E9%AB%98%E9%A2%91%E5%81%9A%E5%B8%82%E5%88%97%22%5D%20--%3E%20Inv%5B%22%E6%97%A5%E5%86%85%E5%BA%93%E5%AD%98%E5%9D%87%E5%80%BC%E5%9B%9E%E5%A4%8D%22%5D%0A%20%20MM%20--%3E%20Spr%5B%22%E8%B5%9A%E5%AE%9E%E7%8E%B0%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20MM%20--%3E%20Ev%5B%22%E6%96%B0%E9%97%BB%E7%AA%97%E5%8F%AF%E8%83%BD%E6%94%B9%E5%90%83%E5%8D%95%22%5D%0A%20%20Inv%20--%3E%20Qual%5B%22%E5%B9%B3%E9%9D%99%E6%9C%9F%E4%BB%B7%E5%B7%AE%20%2F%20%E6%B7%B1%E5%BA%A6%22%5D%0A%20%20Ev%20--%3E%20Qual2%5B%22%E5%8E%8B%E5%8A%9B%E6%9C%9F%E6%92%A4%E9%80%80%E6%88%96%E7%8B%99%E5%87%BB%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>速度对做市的合法用途是更新报价与跨市场对冲，使库存方差在给定成交量下更小，从而能报更窄。这与狙击用同一技术栈。政策若一刀切限制速度，可能同时砍掉做市腿与狙击腿。设计更好的是改变先到者通吃（FBA、颠簸），而不是禁止低延迟库存管理。</p><p>与 Glosten 曲线：高频做市商把曲线的近端变得更厚更闪——平均形状近端浅（寿命短）但补给快。宏观形状的驼峰与「有效可成交深度」因此分叉，执行算法不能只看平均 L2。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单一做市商案例不能代表全体 HFT。美国碎片化、期权、期货各有结构。标记误差会把狙击账户混进做市样本。压力期他们没有义务在场，2010 年闪电崩盘会显示撤退；不能用平静期的价差下降外推危机。中国与欧洲的程序化规则另论，本课不写监管清单。</p><p><span class="marginnote">成交份额 50% 的 HFT 若库存半衰期以秒计，他们承担的五年风险可能仍小于一个隔夜做市商。份额不是风险分担份额。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Menkveld（2013）显示部分 HFT 是日内高频做市：双边、库存回复、隔夜近零。</li><li>速度用于报价更新与对冲时，可压低平静期价差；同一技术也可用于狙击。</li><li>风险被重分配到隔夜持有者，开收盘质量不必同比改善。</li><li>出处：Menkveld, <em>Journal of Financial Economics</em>, 2013；算法交易与流动性见 Hendershott, Jones and Menkveld, <em>Journal of Finance</em>, 2011。</li></ul>',8))])}const f=o(m,[["render",h]]);export{v as __pageData,f as default};
